import{_ as i,o as a,c as r,ai as d}from"./chunks/framework.ampVZV4B.js";const f=JSON.parse('{"title":"提效复盘：哪些真省了时间","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/efficiency-review.md","filePath":"ai/productivity/efficiency-review.md"}'),e={name:"ai/productivity/efficiency-review.md"};function l(n,t,o,h,s,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="提效复盘-哪些真省了时间" tabindex="-1">提效复盘：哪些真省了时间 <a class="header-anchor" href="#提效复盘-哪些真省了时间" aria-label="Permalink to “提效复盘：哪些真省了时间”">​</a></h1><h2 id="场景与问题" tabindex="-1">场景与问题 <a class="header-anchor" href="#场景与问题" aria-label="Permalink to “场景与问题”">​</a></h2><p>用 AI 半年，工具订阅花了钱，感觉上“快了不少”，但具体快在哪、快了多少，说不出来。更麻烦的是两类隐性损失：有些任务用了 AI 反而更慢（生成的代码审了半天，不如自己写）；有些用法一直在坚持，其实从没真正省过时间。还有人囤了一堆提示词和工具，回头发现常用的就是两个。</p><p>没有复盘，AI 用法就会停留在“凭感觉”，钱和时间照花，提升却停滞。提效这件事和性能调优一个道理：先测量，再优化。拍脑袋的“感觉快了”不算数。</p><h2 id="做法" tabindex="-1">做法 <a class="header-anchor" href="#做法" aria-label="Permalink to “做法”">​</a></h2><h3 id="_1-记录-每类任务省了多少时间" tabindex="-1">1. 记录：每类任务省了多少时间 <a class="header-anchor" href="#_1-记录-每类任务省了多少时间" aria-label="Permalink to “1. 记录：每类任务省了多少时间”">​</a></h3><p>按任务类型建一个简单的记录表，每类任务记三个数：<strong>过去做一次的耗时、现在做一次的耗时、质量是否下降</strong>。我的初始分类和大致体感数据（供参考，数值因人而异）：</p><table tabindex="0"><thead><tr><th>任务类型</th><th>过去耗时</th><th>用 AI 后</th><th>体感节省</th></tr></thead><tbody><tr><td>写业务代码（明确需求）</td><td>2h</td><td>0.8h</td><td>明显</td></tr><tr><td>代码 review / 读陌生代码</td><td>1h</td><td>0.5h</td><td>明显</td></tr><tr><td>写周报、纪要、邮件</td><td>40min</td><td>10min</td><td>明显</td></tr><tr><td>查报错、查技术方案</td><td>30min</td><td>10min</td><td>明显</td></tr><tr><td>写技术方案、架构设计</td><td>2h</td><td>1.5h</td><td>一般</td></tr><tr><td>头脑风暴、发散思路</td><td>30min</td><td>20min</td><td>一般</td></tr><tr><td>精确的数据分析、复杂正则</td><td>30min</td><td>40min</td><td>反而更慢</td></tr></tbody></table><p>关键不是数字多精确，是<strong>有数字</strong>。两周记下来，哪类是现金牛、哪类是负资产一目了然。顺便记质量：省了时间但错误率上升的任务（比如 AI 写的 SQL），账要算净的。</p><h3 id="_2-记录失败的用法-写进自己的反例清单" tabindex="-1">2. 记录失败的用法，写进自己的反例清单 <a class="header-anchor" href="#_2-记录失败的用法-写进自己的反例清单" aria-label="Permalink to “2. 记录失败的用法，写进自己的反例清单”">​</a></h3><p>失败比成功更值得记，因为它会重复。几个我真实踩过的：</p><ul><li><strong>让 AI 直接改一个没看懂的大型模块</strong>：产出的 diff 审不动，回滚花了比重写还久。→ 规则：不看懂的改动不接受。</li><li><strong>拿通用模型写长正则并直接上线</strong>：跑起来匹配了不该匹配的。→ 规则：规则类产出必须拿真实样本测过才用。</li><li><strong>长对话不重开</strong>：AI 翻出十轮前的废弃方案接着改，越改越乱。→ 规则：一个任务一个对话。</li><li><strong>周报全交给 AI 不核事实</strong>：数字被它四舍五入“优化”了，差点发出去。→ 规则：具体数据一律回源核对。</li><li><strong>让它生成脚本后没看危险操作</strong>：dry-run 都没有就跑了。→ 规则：批量改动默认 dry-run。</li></ul><p>每条失败记录成“场景 + 后果 + 下次的规则”，规则要写到可以执行的程度，而不是“下次小心”。</p><h3 id="_3-roi-排序-把时间投给回报高的" tabindex="-1">3. ROI 排序，把时间投给回报高的 <a class="header-anchor" href="#_3-roi-排序-把时间投给回报高的" aria-label="Permalink to “3. ROI 排序，把时间投给回报高的”">​</a></h3><p>用节省时间做排序依据：</p><ul><li><strong>高 ROI（加码）</strong>：明确需求的代码实现、模板化文档、报错排查。这些继续深化，把模板和提示词打磨得更顺。</li><li><strong>中 ROI（维持）</strong>：方案设计、读陌生代码。让 AI 当对手盘出初稿，决策自己来，别指望它替你思考。</li><li><strong>负 ROI（砍掉或换用法）</strong>：精确计算、小改动却要审大 diff 的场景。要么回到手做，要么改变用法（比如只让它写草稿、自己誊）。</li><li><strong>算总账</strong>：订阅费 + 你花在“调教 AI”上的时间，对比总节省时间。低于 1:3 的工具或用法，考虑降级或放弃。</li></ul><h3 id="_4-维护一份持续更新的-ai-用法清单" tabindex="-1">4. 维护一份持续更新的 AI 用法清单 <a class="header-anchor" href="#_4-维护一份持续更新的-ai-用法清单" aria-label="Permalink to “4. 维护一份持续更新的 AI 用法清单”">​</a></h3><p>把复盘产出沉淀成一页纸的个人清单，定期（比如每季度）重看修订。我的版本长这样：</p><ul><li>提问用四段式：背景-目标-约束-输出格式。</li><li>一个任务一个对话，项目约定沉淀到规则文件。</li><li>AI 写、我审；看不懂的 diff 不继续。</li><li>不可逆操作默认 dry-run，先小样本后全量。</li><li>具体数字、日期、人名一律回源核对。</li><li>负 ROI 任务（长正则、精确计算）不用 AI。</li><li>每季度按记录表重排 ROI，砍掉不用的订阅。</li></ul><p>清单不求多，每条都必须是复盘里用真金白银换来的，而不是从别人文章里抄的。抄来的清单没有经历过你的失败，执行不下去。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>复盘先测量：按任务类型记“过去耗时 / 现在耗时 / 质量变化”，有数字才有判断。</li><li>失败用法更要记，转成可执行的规则写进反例清单，规则要具体到动作。</li><li>按 ROI 分三档：高 ROI 加码、中 ROI 维持、负 ROI 砍掉。</li><li>算总账：订阅费 + 调教时间 vs 总节省时间，低于 1:3 的降级。</li><li>沉淀成一页纸的个人用法清单，每季度按新数据修订，只留自己验证过的条目。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>提效复盘的本质是把 AI 用法当成一个持续优化的系统：记录是采样，反例是 bug 库，ROI 排序是调优方向，个人清单是配置文件。大多数人用 AI 的提升曲线会在三个月后趋平，因为从不复盘；而每季度认真过一遍记录表的人，能持续把负资产砍掉、把现金牛喂大。省下的不只是时间，还有你花在错误用法上的注意力。</p>',24)])])}const I=i(e,[["render",l]]);export{f as __pageData,I as default};
